-- Initial multi-tenant CRM schema. Generated from prisma/schema.prisma.
CREATE SCHEMA IF NOT EXISTS "public";

CREATE TYPE "MembershipRole" AS ENUM ('OWNER','ADMIN','MANAGER','SELLER','SUPPORT','ANALYST','VIEWER');
